#!/bin/bash
# ============================================================================
#  BOD Bookings — one-shot DigitalOcean droplet bootstrap (cloud-init user data)
#  Paste this whole file into "Advanced Options → Add Initialization scripts (User data)"
#  when creating an Ubuntu 24.04 droplet. Fill in the values in the block below first.
#  The app code is embedded at the bottom; nothing else needs uploading.
# ============================================================================

# ---------------- FILL THESE IN ----------------
DOMAIN="book.backofficedesigns.com"
ADMIN_EMAIL="bill@backofficedesigns.com"          # Let's Encrypt notices
GOOGLE_CLIENT_ID=""                               # from Google Cloud > Credentials (Web client)
GOOGLE_CLIENT_SECRET=""
STRIPE_SECRET_KEY=""                              # optional now; can add later in /var/www/bookings/.env
STRIPE_WEBHOOK_SECRET=""
STRIPE_PRICE_PRO_MONTHLY=""
STRIPE_PRICE_PRO_YEARLY=""
MAIL_FROM="hello@backofficedesigns.com"
# ------------------------------------------------

set -euxo pipefail
exec > /var/log/bookings-bootstrap.log 2>&1
export DEBIAN_FRONTEND=noninteractive

apt-get update
apt-get install -y nginx php8.3-fpm php8.3-mysql php8.3-curl php8.3-mbstring php8.3-xml mysql-server certbot python3-certbot-nginx ufw

# ---- app files ----
mkdir -p /var/www/bookings
cd /var/www/bookings
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d | tar xz
APP_KEY=$(php -r 'echo bin2hex(random_bytes(32));')
DB_PASS=$(php -r 'echo bin2hex(random_bytes(16));')

cat > .env <<ENV
APP_NAME="BOD Bookings"
APP_URL=https://${DOMAIN}
APP_ENV=production
APP_KEY=${APP_KEY}
DB_DSN="mysql:host=127.0.0.1;dbname=bookings;charset=utf8mb4"
DB_USER=bookings
DB_PASS=${DB_PASS}
GOOGLE_CLIENT_ID=${GOOGLE_CLIENT_ID}
GOOGLE_CLIENT_SECRET=${GOOGLE_CLIENT_SECRET}
STRIPE_SECRET_KEY=${STRIPE_SECRET_KEY}
STRIPE_WEBHOOK_SECRET=${STRIPE_WEBHOOK_SECRET}
STRIPE_PRICE_PRO_MONTHLY=${STRIPE_PRICE_PRO_MONTHLY}
STRIPE_PRICE_PRO_YEARLY=${STRIPE_PRICE_PRO_YEARLY}
MAIL_DRIVER=log
MAIL_FROM=${MAIL_FROM}
MAIL_FROM_NAME="BOD Bookings"
FREE_EVENT_TYPES=1
ENV

# ---- database ----
mysql -e "CREATE DATABASE IF NOT EXISTS bookings CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;"
mysql -e "CREATE USER IF NOT EXISTS 'bookings'@'localhost' IDENTIFIED BY '${DB_PASS}'; GRANT ALL ON bookings.* TO 'bookings'@'localhost'; FLUSH PRIVILEGES;"
mysql bookings < migrations/001_init.sql

# ---- permissions ----
chown -R www-data:www-data /var/www/bookings
chmod 640 /var/www/bookings/.env
find /var/www/bookings -type d -exec chmod 750 {} \;
find /var/www/bookings -type f -exec chmod 640 {} \;

# ---- php ----
sed -i 's/^expose_php = On/expose_php = Off/; s/^;session.cookie_secure =.*/session.cookie_secure = 1/' /etc/php/8.3/fpm/php.ini
systemctl restart php8.3-fpm

# ---- nginx (HTTP first; certbot upgrades to HTTPS once DNS resolves) ----
cat > /etc/nginx/sites-available/bookings <<NGX
server {
    listen 80;
    server_name ${DOMAIN};
    root /var/www/bookings/public;
    index index.php;
    add_header X-Content-Type-Options nosniff;
    add_header X-Frame-Options SAMEORIGIN;
    add_header Referrer-Policy strict-origin-when-cross-origin;
    location /assets/ { expires 7d; access_log off; }
    location / { try_files \$uri /index.php\$is_args\$args; }
    location ~ \.php$ {
        include fastcgi_params;
        fastcgi_pass unix:/run/php/php8.3-fpm.sock;
        fastcgi_param SCRIPT_FILENAME \$document_root/index.php;
    }
    location ~ /\. { deny all; }
}
NGX
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/bookings /etc/nginx/sites-enabled/bookings
nginx -t && systemctl reload nginx

# ---- firewall ----
ufw allow OpenSSH
ufw allow 'Nginx Full'
ufw --force enable

# ---- TLS: retry every 5 min until the DNS A record points here, then stop ----
cat > /usr/local/bin/bookings-certbot.sh <<'CB'
#!/bin/bash
DOMAIN=$(grep -oP '^APP_URL=https://\K.*' /var/www/bookings/.env)
MYIP=$(curl -s -4 https://api.ipify.org)
DNSIP=$(getent ahostsv4 "$DOMAIN" | awk '{print $1; exit}')
if [ "$MYIP" = "$DNSIP" ]; then
  certbot --nginx -n --agree-tos -m "$ADMIN_EMAIL_PLACEHOLDER" -d "$DOMAIN" --redirect && systemctl disable --now bookings-certbot.timer
fi
CB
sed -i "s/\$ADMIN_EMAIL_PLACEHOLDER/${ADMIN_EMAIL}/" /usr/local/bin/bookings-certbot.sh
chmod +x /usr/local/bin/bookings-certbot.sh
cat > /etc/systemd/system/bookings-certbot.service <<'SVC'
[Unit]
Description=Obtain TLS cert for BOD Bookings once DNS resolves
[Service]
Type=oneshot
ExecStart=/usr/local/bin/bookings-certbot.sh
SVC
cat > /etc/systemd/system/bookings-certbot.timer <<'TMR'
[Unit]
Description=Retry certbot until DNS points here
[Timer]
OnBootSec=2min
OnUnitActiveSec=5min
[Install]
WantedBy=timers.target
TMR
systemctl daemon-reload
systemctl enable --now bookings-certbot.timer

# ---- daily DB backup (keeps 14) ----
cat > /etc/cron.daily/bookings-backup <<'BK'
#!/bin/bash
mkdir -p /var/backups/bookings && mysqldump bookings | gzip > /var/backups/bookings/$(date +%F).sql.gz
ls -1t /var/backups/bookings/*.sql.gz | tail -n +15 | xargs -r rm
BK
chmod +x /etc/cron.daily/bookings-backup

echo "BOOTSTRAP COMPLETE $(date)" > /var/www/bookings-bootstrap.done
exit 0

__PAYLOAD__

